from pathlib import Path
import json
from decimal import Decimal, ROUND_HALF_UP
def hours(price,factor,rate):return float((Decimal(price)*Decimal(factor)/Decimal(rate)).quantize(Decimal("0.01"),rounding=ROUND_HALF_UP))
HERE=Path(__file__).resolve().parent
prices=[('Эссе / реферат / контрольная',2500),('Курсовая',14000),('Курсовая с исследованием',20000),('Отчёт по практике',14000),('Отдельная глава',30000),('ВКР',40000),('Магистерская',60000),('Статья РИНЦ',9000),('Статья ВАК',18000),('Scopus / WoS',35000),('Кандидатская',200000),('Презентация и речь',6000),('Дополнительный нормоконтроль',5000),('Индивидуальный разбор, час',3000),('Пакет к защите',9500)]
rows=[]
for name,price in prices:
 rows.append({'name':name,'price':price,'baseHours1000':hours(price,'0.67',1000),'stressHours500':hours(price,'0.4275',500),'stressHours1000':hours(price,'0.4275',1000),'stressHours1500':hours(price,'0.4275',1500)})
lines=['# Экономика раздела услуг — 27 сентября 2026','',
'Собственник выполняет работы сам. Все опубликованные цены сохранены. Новые числовые значения для неопределённых задач — предварительная модель бюджета с названным объёмом, а не изменение прайса. Этот документ и калькулятор предназначены владельцу; в публичный сайт не включаются.','',
'## Решение','',
'Конкурировать обещанием самой низкой цены при текущем прайсе нельзя. Рабочая позиция: понятный объём, личное выполнение, прозрачные дополнения, смета до оплаты, выбор части вместо всей работы и действующие бонусы. Прибыль обеспечивает ограничение оплачиваемого объёма и времени, а не новая бесконтрольная скидка. Увеличение конверсии и выручки пока не измерено.','',
'## Рыночная сверка','',
'Проверено 27.09.2026 по публичным страницам самих сервисов. Это рекламные минимумы, а не средние чеки и не персональные сметы на одинаковое задание. Качество и равенство состава не проверялись.','',
'| Сервис | Курсовая от | Диплом от | Магистерская от | Источник |','|---|---:|---:|---:|---|',
'| Заочник | 1 800 ₽ | 7 950 ₽ (ВКР 7 000 ₽) | 20 000 ₽ | https://zaochnik.ru/uslugi_i_ceny/ |',
'| Homework | 2 300 ₽ | 11 900 ₽ | 15 000 ₽ | https://www.homework.ru/uslugi/ |',
'| Студворк | 1 000 ₽ | 5 000 ₽ | не использовано | https://studwork.ru/ (свежий поисковый снимок; прямое открытие завершилось тайм-аутом) |',
'| Академический Салон | 14 000 ₽ | 40 000 ₽ | 60 000 ₽ | https://akademsalon.ru/services.html |','',
'Заочник и Homework прямо указывают зависимость стоимости от объёма, сложности и срока. Поэтому утверждения «мы дешевле всех», «конкуренты обязательно доплатят» или подмена их минимальной цены полной сметой не используются. Оформление и правки также рекламируются конкурентами: сами по себе это не уникальное преимущество. Проверяемое преимущество нового интерфейса — открытая структура собственного расчёта без оставленных пустыми цен.','',
'## Действующие выгоды','',
'Источник: опубликованные salon-benefits.js, salon-commerce.js, app.js из hash-pinned release223; страницы https://akademsalon.ru/benefits.html и https://akademsalon.ru/plus.html.','',
'- Салон+: 449 ₽ / 30 дней или 999 ₽ / 150 дней; 5%, до 1 000 ₽ на заказ. Про: 1 190 / 2 690 ₽; 10%, до 3 000 ₽. Сессия: 2 990 ₽ / 60 дней; 7%, до 2 000 ₽. В расчёте новой покупки стоимость подписки включена. Для существующей — это уже понесённый расход, отдельный режим.','- Скидка подписки и промокод работают best-of. Баллы: не более 20% цены; скидка плюс списание — не более 25%. Промокод ПЕРВЫЙЛИСТ истёк 21.09.2026 и не активируется в новом интерфейсе. При иной действующей акции итог требует серверной проверки.','- Кешбэк 5% денежной части после полной оплаты, Про — 10%. Сертификат не даёт кешбэк на погашенную им часть. Будущие баллы не вычитаются из оплаты этого заказа.','- Депозит: 20/30/45/60 тыс. ₽; резерв до 8/10/12/15%. Учитывается фактическое использование; из начисления вычитается кешбэк. Дополнительный резерв после приёмки и 14 дней. Это аванс, не доходность вложений. Нельзя учитывать и 15% резерва, и ещё 10% кешбэка как независимые 25%.','- Для расчёта рентабельности в этой управленческой модели аванс не считаем заработанной выручкой до оказания услуг; это не инструкция по налоговому учёту. Неиспользованный остаток — обязательство вернуть деньги. Этап покрывается целиком; смешанный платёж из недостаточного депозита не обещается. Сертификат — оплаченный ранее способ расчёта, а не скидка.','- Реферальные 200 баллов возникают один раз после оплаты первым новым клиентом; нельзя обещать их каждому покупателю. Цифровые подарки за проверенные подписки на каналы остаются доступными по существующим правилам.','- Презентация/речь 6 000 ₽ + нормоконтроль 5 000 ₽ объединяются в уже действующий пакет 9 500 ₽. Экономия 1 500 ₽ относится к этим двум услугам, не к цене основной работы. Индивидуальный разбор 3 000 ₽/час.','',
'## Окупаемость подписки только скидками','',
'Без будущего кешбэка, промокодов и имеющихся баллов. Для работ одной цены внутри срока действия.','',
'| Сценарий | Без подписки | Салон+ 150 дней | Про 150 дней | Выбор по прямым расходам |','|---|---:|---:|---:|---|',
'| 1 курсовая × 14 000 | 14 000 | 14 299 | 15 290 | Без подписки |',
'| 3 курсовые × 14 000 | 42 000 | 40 899 | 40 490 | Про: экономия 1 510 |',
'| 1 ВКР × 40 000 | 40 000 | 39 999 | 39 690 | Про: экономия 310 |',
'| 1 эссе × 2 500 | 2 500 | 3 374 | 4 940 | Без подписки |','',
'Порог окупаемости для курсовой: Салон+ 150 дней — со второго заказа, Про — со второго. Для Сессии три курсовые дают скидку 2 940 ₽, меньше стоимости 2 990 ₽; её продают за кураторские функции, а не как лучшую скидку. Сессию нельзя сравнивать с семестром без явного различия 60 и 150 дней.','',
'## Модель прибыли и допущения','',
'Фактические часы, затраты, конверсия и рекламная стоимость клиента не предоставлены. Ниже сценарии, а не гарантия прибыли. Стандартные допущения: переменные денежные расходы 8% поступлений (условный совокупный резерв, не установленная налоговая ставка), желаемая прибыль 20% поступлений после оплаты собственного труда, 100% новых бонусов резервируются рубль за рубль, 20% времени дополнительно на коммуникацию и правки. CAC и фиксированные расходы задаются в интерактивном файле.','',
'G — цена по прайсу; D — скидка и использованные баллы; R = G − D — признанная выручка за услуги (включая оплаченный ранее сертификат/аванс). B — новый резерв бонусов. c — переменные расходы; F — фиксированные расходы и привлечение; h — часы; r — ставка часа.','',
'Прибыль = R − B − c × R − F − r × h × 1,20.','Предельное время с учётом коммуникации/правок при целевой марже m: H = max(0, (R − B − c × R − F − m × R) / r).','Чистое производственное время: H / 1,20. Уже использованные баллы снижают R; их прошлый резерв нельзя второй раз отнести на расход этого же заказа. Для консервативного планирования здесь одновременно предусмотрены текущее списание и новые начисления. Подписочная выручка не субсидирует каждый заказ повторно.','',
'Базовый сценарий: нет скидок/списаний, новый кешбэк 5%, расходы 8%, прибыль 20% → H = 0,67 × G / r. Стресс: списания и скидки 25%, новые бонусы до 15% оставшейся выручки, расходы 8%, прибыль 20% → H = 0,4275 × G / r. Это консервативный потолок нагрузки, а не обещание, что каждый клиент получит все максимумы.','',
'## Допустимые часы на заказ (включая переписку и правки)','',
'| Услуга | Цена ₽ | База, 1 000 ₽/ч | Стресс, 500 ₽/ч | Стресс, 1 000 ₽/ч | Стресс, 1 500 ₽/ч |','|---|---:|---:|---:|---:|---:|']
for r in rows:lines.append('| '+r['name']+' | '+str(r['price'])+' | '+' | '.join(f'{r[k]:.2f}' for k in ['baseHours1000','stressHours500','stressHours1000','stressHours1500'])+' |')
lines += ['', 'При курсовой за 14 000 ₽ и ставке 1 000 ₽/час: базовый лимит 9,38 ч, стрессовый — 5,99 ч; чистого производства соответственно 7,82 и 4,99 ч. При 8 ч производства +20% на правки прибыль базы 2 580 ₽, стресса −1 515 ₽. Следовательно, нельзя считать любую курсовую прибыльной только потому, что цена 14 000 ₽. Сложные требования требуют дополнительного согласованного объёма, другого графика или отказа от неподъёмной задачи — без снижения базовой цены.', '',
'## Новые ориентиры без изменения тарифов','',
'- Небольшой фрагмент до 5 страниц / одна небольшая задача: бюджет от существующей малой работы 2 500 ₽. Количество 1–10 считается линейно, крупный проект не маскируется под один фрагмент.','- Редактура: явный выбор вида работы и его существующей ставки; по умолчанию этап курсовой 9 000 ₽, практика 8 000 ₽, ВКР 24 000 ₽ и т. д.','- Блок расчётов на готовых данных: бюджет от редакторского этапа курсовой 9 000 ₽, метод и сложность подтверждаются. Это допущение модели, не обещание любого исследования за эту сумму.','- Срок меньше суток: диапазон 2–3× от плановой основы, закреплённый 24-часовой коэффициент 2× не изменён. Исполнимость и точный срок согласуются. Кандидатская целиком не получает экспресс.','- VIP: существующие дополнения + резерв координации max(3 000 ₽, 15% цены работы). Для курсовой: 14 000 + 9 500 + 3 000 + 3 000 = 29 500 ₽ по нижней границе. Резерв 3 000 ₽ при стрессовых условиях и 1 000 ₽/ч даёт 1,28 ч координации при целевой марже; нельзя обещать безлимитные консультации. Итерации и срок фиксируются.','',
'## Продажи и дополнительные покупки','',
'1. Продавать нужный следующий результат: небольшая часть → основная работа → подготовка к защите, без обещаний зачёта стоимости предыдущего этапа там, где такого правила нет.','2. Показывать комплект 9 500 ₽ только при реальной потребности в обоих дополнениях. Услуга, выбранная как основная, не добавляется второй раз. Базовое оформление не выдаётся за платный нормоконтроль.','3. Подписку рекомендовать по чистой экономии после её цены и реальному числу работ; цифровые материалы и куратор — отдельная полезность, без придуманной денежной оценки.','4. Новая бесплатная польза: копирование личной сметы, расчёт выгод, сравнение подписок и сохранение выбора. После разработки почти нулевая стоимость обслуживания, без новой денежной выдачи.','5. Депозит предлагать для уже запланированных услуг, не ради «процентов». Не планировать расходовать весь полученный аванс: учитывать возвратный денежный остаток и бонусный резерв.','6. Перед подтверждением сметы оценить часы, резерв правок, платные источники/инструменты, привлечение и затраты подписочных консультаций. Если трудовой лимит превышен — изменить согласованный объём/этапы или смету допработ; цены прайса не снижать.','',
'## Контроль после запуска','',
'Измерять по реальным завершённым заказам: часы по услугам, выручку после скидок, заработанную ставку часа, расход бонусов, затраты на привлечение, долю допуслуг, возвраты, длительность правок. Результат считать на 10–20 сопоставимых заказах, отдельно по услугам; рост среднего чека не считать ростом прибыли без часов и расходов. Никаких новых аналитических событий/личных данных этим релизом не добавлено.','']
(HERE/'ECONOMICS.md').write_text('\n'.join(lines));(HERE/'economics-data.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
html='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Экономика Салона — рабочая модель владельца</title><style>*{box-sizing:border-box}body{font:16px/1.55 system-ui;background:#f5f4ef;color:#20211e;margin:0;padding:40px 5%}main{max-width:1200px;margin:auto}h1{font-size:clamp(32px,5vw,58px);letter-spacing:-.05em;line-height:1.08}h2{font-size:27px}p{color:#606457;max-width:900px}small{color:#62665d}.fields{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;padding:24px;background:white;border:1px solid #dcded4;border-radius:18px}label{font-size:13px;color:#606457}input,select{display:block;width:100%;font:inherit;color:#20211e;margin-top:8px;min-height:46px;padding:9px;border:1px solid #c9cdbf;border-radius:8px}.numbers{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:24px 0}.numbers>div{padding:24px;background:#eeecfb;border-radius:16px}.numbers strong{display:block;font-size:30px;color:#5148dc;letter-spacing:-.04em}button{min-height:44px;background:#5148dc;color:white;border:0;border-radius:8px;padding:10px 20px;margin:8px 8px 18px 0;font:inherit;cursor:pointer}table{border-collapse:collapse;width:100%;font-size:13px;background:white}th,td{padding:12px;text-align:right;border-bottom:1px solid #e0e1d9}th:first-child,td:first-child{text-align:left}.table{overflow:auto}#verdict{padding:20px;border:1px solid #c2c9b8;border-radius:12px;color:#20211e}a{color:#5148dc}.bad{color:#a52620!important}@media(max-width:760px){body{padding:22px 18px}.fields,.numbers{grid-template-columns:1fr 1fr}}@media(max-width:400px){.fields,.numbers{grid-template-columns:1fr}}</style><main><small>АКАДЕМИЧЕСКИЙ САЛОН · ДЛЯ ВЛАДЕЛЬЦА · 27.09.2026</small><h1>Цена сохраняется.<br>Прибыль считается.</h1><p>Подставьте часы и расходы. Модель резервирует новые бонусы целиком, оплачивает ваш труд и показывает остаток. Все значения — сценарии; фактических данных о трудозатратах и налоговом режиме нет.</p><button id="base">Обычный заказ</button><button id="stress">Максимальная нагрузка бонусами</button><div class="fields"><label>Услуга<select id="service"></select></label><label>Цена заказа, ₽<input id="price" type="number" min="1" value="14000"></label><label>Час вашего труда, ₽<select id="rate"><option>500</option><option selected>1000</option><option>1500</option><option>2000</option></select></label><label>Чистых часов работы<input id="hours" type="number" min="0" value="8" step="0.5"></label><label>Переписка и правки, % времени<input id="buffer" type="number" min="0" max="200" value="20"></label><label>Скидка + списание, %<input id="discount" type="number" min="0" max="25" value="0"></label><label>Новые бонусы, % выручки<input id="bonus" type="number" min="0" max="15" value="5"></label><label>Переменные расходы, % выручки<input id="cost" type="number" min="0" max="100" value="8"></label><label>Привлечение клиента, ₽<input id="cac" type="number" min="0" value="0"></label><label>Инструменты / прочие расходы, ₽<input id="fixed" type="number" min="0" value="0"></label><label>Целевая прибыль, % выручки<input id="margin" type="number" min="0" max="80" value="20"></label></div><div class="numbers" aria-live="polite"><div>После скидок<strong id="revenue"></strong></div><div>Труд с резервом<strong id="labor"></strong></div><div>Прибыль после труда<strong id="profit"></strong></div><div>Лимит всех часов<strong id="capacity"></strong></div></div><p id="verdict"></p><p><b>Формула:</b> прибыль = выручка после скидок − резерв новых бонусов − переменные расходы − привлечение − инструменты − часы × ставка × резерв правок. Депозит и сертификат учитываются как ранее оплаченные деньги, а не дополнительные скидки. Подписочная выручка здесь не приписывается повторно каждому заказу.</p><h2>Потолок времени при марже 20%</h2><p>База: 5% новых бонусов, без скидок. Стресс: 25% текущей выгоды, 15% новых бонусов. Переменные расходы 8%; CAC и фиксированные расходы в таблице 0. Часы включают переписку и правки, чистого производства — общее время, делённое на 1,20.</p><div class="table"><table><thead><tr><th>Услуга</th><th>Цена</th><th>База<br>1 000 ₽/ч</th><th>Стресс<br>500 ₽/ч</th><th>Стресс<br>1 000 ₽/ч</th><th>Стресс<br>1 500 ₽/ч</th></tr></thead><tbody id="table"></tbody></table></div><h2>Рынок и правила</h2><p>Полная записка с исследованием рынка, выгодами, порогами подписок и правилами продажи: <a href="ECONOMICS.md">ECONOMICS.md</a>. Рекламные минимумы <a href="https://zaochnik.ru/uslugi_i_ceny/">Заочника</a> и <a href="https://www.homework.ru/uslugi/">Homework</a> ниже вашего прайса, но не являются сопоставимыми индивидуальными сметами. Обещание «дешевле всех» не используется.</p><script>const rows=__ROWS__;const $=id=>document.getElementById(id),f=n=>Math.round(n).toLocaleString('ru-RU')+' ₽';$('service').innerHTML=rows.map((r,i)=>'<option value="'+i+'">'+r.name+'</option>').join('');$('service').value='1';$('table').innerHTML=rows.map(r=>'<tr><td>'+r.name+'</td><td>'+f(r.price)+'</td>'+['baseHours1000','stressHours500','stressHours1000','stressHours1500'].map(k=>'<td>'+r[k].toFixed(2)+'</td>').join('')+'</tr>').join('');function render(){const inputs=[...document.querySelectorAll('input')];if(inputs.some(i=>!i.value||!i.validity.valid)){$('verdict').textContent='Укажите допустимые значения во всех полях.';['revenue','labor','profit','capacity'].forEach(id=>$(id).textContent='—');return}const n=id=>Number($(id).value),revenue=n('price')*(1-n('discount')/100),reserve=revenue*n('bonus')/100,variable=revenue*n('cost')/100,fixed=n('cac')+n('fixed'),labor=n('rate')*n('hours')*(1+n('buffer')/100),profit=revenue-reserve-variable-fixed-labor,limit=Math.max(0,(revenue-reserve-variable-fixed-revenue*n('margin')/100)/n('rate'));$('revenue').textContent=f(revenue);$('labor').textContent=f(labor);$('profit').textContent=f(profit);$('profit').className=profit<0?'bad':'';$('capacity').textContent=(Math.round((limit+Number.EPSILON)*100)/100).toFixed(2)+' ч';$('verdict').textContent='Резерв новых бонусов: '+f(reserve)+'. Переменные расходы: '+f(variable)+'. Маржа после оплаты труда: '+(profit/revenue*100).toFixed(1)+'%. Для цели '+n('margin')+'% чистая работа должна занять не больше '+(limit/(1+n('buffer')/100)).toFixed(2)+' ч. '+(profit<revenue*n('margin')/100?'Текущий объём не укладывается в целевую прибыль. Уточните трудозатраты и согласованный объём до подтверждения заказа.':'Сценарий выдерживает целевую прибыль.')};document.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',render));$('service').onchange=()=>{$('price').value=rows[$('service').value].price;render()};$('base').onclick=()=>{$('discount').value=0;$('bonus').value=5;render()};$('stress').onclick=()=>{$('discount').value=25;$('bonus').value=15;render()};render();</script></main></html>'''
(HERE/'economics.html').write_text(html.replace('__ROWS__',json.dumps(rows,ensure_ascii=False)))
print('Wrote ECONOMICS.md, economics.html, economics-data.json')
